    \"state\": \"consequatur\",
    \"postal_code\": \"consequatur\",
    \"country\": \"consequatur\",
    \"is_default\": true,
    \"type\": \"consequatur\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/v1/addresses/1"
);

const headers = {
    "Authorization": "Bearer {YOUR_API_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "label": "Office",
    "first_name": "John",
    "last_name": "Doe",
    "company": "consequatur",
    "phone": "consequatur",
    "address_line1": "consequatur",
    "address_line2": "consequatur",
    "city": "consequatur",
    "state": "consequatur",
    "postal_code": "consequatur",
    "country": "consequatur",
    "is_default": true,
    "type": "consequatur"
};

fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

