    \"wholesale_100_plus_price\": 25,
    \"wholesale_100_acquisition_cost\": 12,
    \"sale_mode\": \"both\",
    \"status\": \"active\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://127.0.0.1:8000/api/v1/seller/offers/1"
);

const headers = {
    "Authorization": "Bearer {YOUR_API_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "retail_price": 34.99,
    "retail_acquisition_cost": 18,
    "wholesale_10_99_price": 30,
    "wholesale_10_99_acquisition_cost": 14,
    "wholesale_100_plus_price": 25,
    "wholesale_100_acquisition_cost": 12,
    "sale_mode": "both",
    "status": "active"
};

fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

