    &quot;status&quot;: true,
    &quot;message&quot;: &quot;Reply sent.&quot;,
    &quot;data&quot;: {
        &quot;id&quot;: 4,
        &quot;sender_role&quot;: &quot;customer&quot;,
        &quot;message&quot;: &quot;Could you please check the order again?&quot;,
        &quot;created_at&quot;: &quot;2026-02-28T15:00:00.000000Z&quot;
    }
}</code>
 </pre>
